  // --- more passkeys, one-time codes for another device (#95) ---
  '1 passkey': '1 klucz dostępu',
  'A one-time code lets your phone or another computer sign in with a passkey of its own.': 'Kod jednorazowy pozwala twojemu telefonowi lub innemu komputerowi logować się własnym kluczem dostępu.',
  'Add a passkey': 'Dodaj klucz dostępu',
  'Add another device': 'Dodaj kolejne urządzenie',
  'Add this device': 'Dodaj to urządzenie',
  'Added {0}': 'Dodano {0}',
  'Code from your other device': 'Kod z drugiego urządzenia',
  'Confirm with a passkey': 'Potwierdź kluczem dostępu',
  'Confirmed. Now create the new passkey; your browser will ask where to keep it.': 'Potwierdzono. Teraz utwórz nowy klucz dostępu; przeglądarka zapyta, gdzie go zapisać.',
  'Copy link': 'Kopiuj link',
  'Create a passkey on this device for the profile “{0}”. It signs you in here from now on.': 'Utwórz na tym urządzeniu klucz dostępu dla profilu „{0}”. Od teraz będziesz się nim tu logować.',
  'Each one signs in to this profile from the device or password manager that keeps it. Tap one to rename or remove it.': 'Każdy z nich loguje do tego profilu z urządzenia lub menedżera haseł, w którym jest zapisany. Dotknij jednego, aby zmienić jego nazwę albo go usunąć.',
  'Enter the code from your other device.': 'Wpisz kod z drugiego urządzenia.',
  'For this device, a security key, a password manager, or your phone through the browser’s own QR code. First confirm that it is you.': 'Dla tego urządzenia, klucza bezpieczeństwa, menedżera haseł albo twojego telefonu przez kod QR samej przeglądarki. Najpierw potwierdź, że to ty.',
  'It can no longer sign in to this profile. A device already signed in with it stays signed in. If it was lost, use Sign out everywhere.': 'Nie będzie już można się nim zalogować do tego profilu. Urządzenie, które jest nim już zalogowane, pozostanie zalogowane. Jeśli zostało zgubione, użyj „Wyloguj się wszędzie”.',
  'It is your only way in, so it cannot be removed until there is another.': 'To twój jedyny sposób wejścia, więc nie można go usunąć, dopóki nie będzie innego.',
  'Last used {0}': 'Ostatnio użyty {0}',
  'Make a new code': 'Utwórz nowy kod',
  'Name, e.g. Work laptop': 'Nazwa, np. Laptop służbowy',
  'None yet. Add one and sign in without your password.': 'Jeszcze żadnego. Dodaj klucz dostępu i loguj się bez hasła.',
  'Passkey added': 'Dodano klucz dostępu',
  'Passkey removed': 'Usunięto klucz dostępu',
  'Passkey {0}': 'Klucz dostępu {0}',
  'Passkeys': 'Klucze dostępu',
  'Remove passkey': 'Usuń klucz dostępu',
  'Remove this passkey?': 'Usunąć ten klucz dostępu?',
  'Scan this with the other device, or open openGym there and enter the code on the sign-in screen. It works once, for {0} minutes.': 'Zeskanuj to drugim urządzeniem albo otwórz tam openGym i wpisz kod na ekranie logowania. Działa raz, przez {0} minut.',
  'That code is wrong, already used or expired. Make a new one on your other device.': 'Ten kod jest błędny, już użyty albo wygasł. Utwórz nowy na drugim urządzeniu.',
  'This browser cannot confirm with your passkey. Do this on a device that holds one.': 'Ta przeglądarka nie może potwierdzić twoim kluczem dostępu. Zrób to na urządzeniu, na którym go masz.',
  'First confirm that it is you.': 'Najpierw potwierdź, że to ty.',
  'This profile has no passkey, and this server does not take passwords, so nothing here can confirm that it is you. Ask your admin.': 'Ten profil nie ma żadnego klucza dostępu, a ten serwer nie przyjmuje haseł, więc nic tutaj nie potwierdzi, że to ty. Zwróć się do administratora.',
  'This browser cannot create passkeys, so it cannot be added with a code. Open the link in a browser that can.': 'Ta przeglądarka nie potrafi tworzyć kluczy dostępu, więc nie można jej dodać kodem. Otwórz link w przeglądarce, która to potrafi.',
  'This browser is signed in as “{0}”. Adding it to “{1}” signs “{0}” out here.': 'Ta przeglądarka jest zalogowana jako „{0}”. Dodanie jej do „{1}” wyloguje tu „{0}”.',
  'This code is for a different profile that is also called “{0}”, not the one this browser is signed in as. Adding it there signs yours out here.': 'Ten kod należy do innego profilu, który też nazywa się „{0}”, a nie do tego, na który zalogowana jest ta przeglądarka. Dodanie jej tam wyloguje tu twój profil.',
  'Only continue if this code comes from a device of your own. This browser is then signed in to “{0}”, and what you log here goes to that profile.': 'Kontynuuj tylko wtedy, gdy ten kod pochodzi z twojego własnego urządzenia. Ta przeglądarka zostanie wtedy zalogowana do „{0}”, a to, co tu zapiszesz, trafi do tego profilu.',
  'This code has expired.': 'Ten kod wygasł.',
  'This device already has a passkey for this profile.': 'To urządzenie ma już klucz dostępu dla tego profilu.',
  'This passkey already belongs to a profile.': 'Ten klucz dostępu należy już do jakiegoś profilu.',
  'This profile already has as many passkeys as it can hold.': 'Ten profil ma już maksymalną liczbę kluczy dostępu.',
  'Use a code from your other device': 'Użyj kodu z drugiego urządzenia',
  'You get a code that lets your phone or another computer create a passkey for this profile. First confirm that it is you.': 'Dostaniesz kod, dzięki któremu twój telefon lub inny komputer utworzy klucz dostępu dla tego profilu. Najpierw potwierdź, że to ty.',
  'or with your password': 'albo swoim hasłem',
  '{0} passkeys': { one: '{0} klucz dostępu', few: '{0} klucze dostępu', many: '{0} kluczy dostępu', other: '{0} klucza dostępu' },
