  'Enter a weight and 1–{0} reps. Beyond that it’s basically guesswork.': 'Podaj ciężar i 1–{0} powtórzeń. Powyżej tego to już właściwie zgadywanie.',
  'Best estimated 1RM:': 'Najlepszy szacowany 1RM:',
