  'Follow the routine ({0})': 'Zgodnie z planem ({0})',
  'Applies to every exercise in this routine that does not set its own rule.': 'Dotyczy każdego ćwiczenia w tym planie, które nie ma własnej zasady.',
  'Step ({0})': 'Skok ({0})',
