  'No automatic progression': 'Bez automatycznej progresji',
  'The next regular target continues from the last included workout.': 'Następny zwykły cel bazuje na ostatnim uwzględnionym treningu.',
  'Deload routine': 'Plan deloadowy',
  'Its workouts do not count toward progression. They still show in history and statistics.': 'Treningi z tego planu nie wliczają się do progresji. Nadal są widoczne w historii i statystykach.',
  'A deload routine opens at the numbers set here, so the progression above does not apply to it.': 'Plan deloadowy zaczyna się od ustawionych tutaj wartości, więc progresja powyżej go nie dotyczy.',
  'Linear progression': 'Progresja liniowa',
  'Greyskull LP': 'Greyskull LP',
  'Double progression': 'Podwójna progresja',
  'Add time': 'Dodawaj czas',
  'Targets stay where you set them.': 'Cele zostają takie, jakie ustawisz.',
  'Hit every rep in every set and the weight goes up. Repeated misses trigger a deload.': 'Wykonaj wszystkie powtórzenia we wszystkich seriach, a ciężar rośnie. Powtarzające się niepowodzenia wywołują deload.',
  'Two straight sets plus a final set taken to failure. Beat the target on that set and the weight goes up (twice as much if you double the reps). One failure resets 10 %.': 'Dwie zwykłe serie plus ostatnia do upadku. Pobij cel w tej serii, a ciężar rośnie (podwójnie, jeśli podwoisz powtórzenia). Jedno niepowodzenie cofa o 10 %.',
  'Work up through a rep range at the same weight. Reach the top of the range in every set and the weight goes up, reps back to the bottom.': 'Pracuj w zakresie powtórzeń na tym samym ciężarze. Osiągnij górną granicę we wszystkich seriach, a ciężar rośnie, a powtórzenia wracają na dół.',
  'Hold every set for the full duration and the target goes up.': 'Wytrzymaj każdą serię pełny czas, a cel rośnie.',
  'Nothing logged yet, so this session sets the baseline.': 'Nic jeszcze nie zapisano, więc ta sesja wyznacza punkt wyjścia.',
  'Held every set for the full time. Target goes up by {0}s.': 'Każda seria wytrzymana pełny czas. Cel rośnie o {0} s.',
  'Short {0} sessions in a row. Back off to {1}s and build up again.': { one: '{0} sesja z rzędu poniżej celu. Zejdź do {1} s i buduj od nowa.', few: '{0} sesje z rzędu poniżej celu. Zejdź do {1} s i buduj od nowa.', many: '{0} sesji z rzędu poniżej celu. Zejdź do {1} s i buduj od nowa.', other: '{0} sesji z rzędu poniżej celu. Zejdź do {1} s i buduj od nowa.' },
  'Came up short last time. Same target again.': 'Ostatnio zabrakło. Ten sam cel jeszcze raz.',
  'Top of the rep range in every set. {0} {1} more, back to {2} reps.': 'Górna granica zakresu w każdej serii. {0} {1} więcej, powrót do {2} powtórzeń.',
  'Stuck for {0} sessions. Deload to {1} {2}.': 'Zastój od {0} sesji. Deload do {1} {2}.',
  'Same weight, aim for {0} reps this time.': 'Ten sam ciężar, tym razem celuj w {0} powtórzeń.',
  'Last set hit {0} reps, twice the target! Take a double jump of {1} {2}.': 'Ostatnia seria to {0} powtórzeń, dwa razy więcej niż cel! Czas na podwójny skok o {1} {2}.',
  'Every rep last time. {0} {1} more.': 'Ostatnio wszystkie powtórzenia. {0} {1} więcej.',
  'Every rep last time. {0} {1} less help.': 'Ostatnio wszystkie powtórzenia. {0} {1} mniej pomocy.',
  'Top of the rep range in every set. {0} {1} less help, back to {2} reps.': 'Górna granica zakresu w każdej serii. {0} {1} mniej pomocy, powrót do {2} powtórzeń.',
  'Missed reps. {0} {1} of help while you build back up.': 'Zabrakło powtórzeń. {0} {1} pomocy, aż znów się rozkręcisz.',
  'Stuck for {0} sessions. Back to {1} {2} of help, then build up again.': 'Zastój od {0} sesji. Wróć do {1} {2} pomocy i buduj od nowa.',
  'Missed reps {0} sessions running. Reset to {1} {2} and work back up.': 'Brakujące powtórzenia w {0} sesjach z rzędu. Wróć do {1} {2} i buduj od nowa.',
  'Missed reps. Reset to {0} {1} and work back up.': 'Zabrakło powtórzeń. Wróć do {0} {1} i buduj od nowa.',
  'Missed reps last time. Same weight again ({0} of {1} to go).': 'Ostatnio zabrakło powtórzeń. Ten sam ciężar jeszcze raz (zostało {0} z {1}).',
  'Bodyweight: every rep last time, so go for {0} this time.': 'Masa własna: ostatnio wszystkie powtórzenia, więc tym razem celuj w {0}.',
  'Bodyweight: same target again until every set is clean.': 'Masa własna: ten sam cel, dopóki każda seria nie będzie czysta.',

  // --- effort per set (RIR / RPE) ---
  '{0} sets bring an {1} with them. Switch on Effort per set in Settings to see it.': { one: '{0} seria ma zapisane {1}. Włącz „Wysiłek na serię” w Ustawieniach, aby to zobaczyć.', few: '{0} serie mają zapisane {1}. Włącz „Wysiłek na serię” w Ustawieniach, aby to zobaczyć.', many: '{0} serii ma zapisane {1}. Włącz „Wysiłek na serię” w Ustawieniach, aby to zobaczyć.', other: '{0} serii ma zapisane {1}. Włącz „Wysiłek na serię” w Ustawieniach, aby to zobaczyć.' },
  '{0} sets bring an {1} with them.': { one: '{0} seria ma zapisane {1}.', few: '{0} serie mają zapisane {1}.', many: '{0} serii ma zapisane {1}.', other: '{0} serii ma zapisane {1}.' },
  'RIR': 'RIR',
  'RPE': 'RPE',
  'Effort per set': 'Wysiłek na serię',
  'What are RIR and RPE?': 'Czym są RIR i RPE?',
  'How hard a set was, logged next to weight and reps. Two scales for the same judgement, counted from opposite ends.': 'Jak ciężka była seria, zapisane obok ciężaru i powtórzeń. Dwie skale tej samej oceny, liczone z przeciwnych stron.',
  'How it felt': 'Jak to było',
  'Nothing left, went to failure': 'Nic nie zostało, do upadku',
  'One more rep in the tank': 'Jeszcze jedno powtórzenie w zapasie',
  'Two more reps': 'Jeszcze dwa powtórzenia',
  'Three more reps': 'Jeszcze trzy powtórzenia',
  'Easy, warm-up territory': 'Lekko, poziom rozgrzewki',
  'Maybe half a rep left': 'Może pół powtórzenia w zapasie',
  'How hard was that set?': 'Jak ciężka była ta seria?',
  'Tap how many reps you had left, or type an exact {0}.': 'Dotknij, ile powtórzeń zostało w zapasie, lub wpisz dokładną wartość {0}.',
  'Exact {0}': 'Dokładne {0}',
  'Clear rating': 'Wyczyść ocenę',
  'RIR counts the reps you left in the tank; RPE reads the same effort off a 10-point scale, so RPE ≈ 10 − RIR. Pick whichever you already think in.': 'RIR liczy powtórzenia, które zostały w zapasie; RPE odczytuje ten sam wysiłek w skali 10, czyli RPE ≈ 10 − RIR. Wybierz tę, w której już myślisz.',
  'The highlighted row is where most working sets land. Sets you have already logged keep their own scale, and nothing else reads the value, so progression and estimated 1RM are unaffected.': 'Wyróżniony wiersz to miejsce, w które trafia większość serii roboczych. Zapisane wcześniej serie zachowują swoją skalę, a nic innego tej wartości nie czyta, więc progresja i szacowany 1RM pozostają bez zmian.',
  // --- effort in the stats ---
  'Effort': 'Wysiłek',
  'how close to failure': 'jak blisko upadku',
  'by hard sets': 'wg ciężkich serii',
