  'Your name, your sign-in details and everything else about your account stay here. Other people’s data is never included.': 'Twoje imię, dane logowania i wszystko inne z twojego konta zostaje tutaj. Dane innych osób nigdy nie są dołączane.',
  'The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.': 'Trener nie jest lekarzem ani fizjoterapeutą. Jeśli coś boli, skonsultuj się ze specjalistą.',
