  'min': 'min',
  'The Coach fits the volume to the time you actually have, including rest between sets.': 'Trener dopasuje objętość do czasu, który naprawdę masz, wliczając przerwy między seriami.',
  'What can you train with?': 'Czym możesz trenować?',
  'Pick everything you have access to. Leave it empty and the Coach will use the whole library.': 'Zaznacz wszystko, do czego masz dostęp. Jeśli zostawisz puste, Trener użyje całej biblioteki.',
  'Anything to work around?': 'Coś, co trzeba obejść?',
  'Injuries, joints that complain, movements you cannot do, or practical limits like training at 6am in a flat.': 'Kontuzje, bolące stawy, ruchy, których nie możesz wykonać, albo ograniczenia praktyczne, np. trening o 6 rano w mieszkaniu.',
  'e.g. “dodgy left shoulder, no barbell overhead press”': 'np. „wrażliwy lewy bark, bez wyciskania sztangi nad głowę”',
  'If something actually hurts, see a professional. The Coach will program conservatively, but it can’t diagnose anything.': 'Jeśli coś naprawdę boli, idź do specjalisty. Trener zaplanuje ostrożnie, ale niczego nie zdiagnozuje.',
