  '"{0}" and its equipment list will be removed.': '„{0}” i jego lista sprzętu zostaną usunięte.',
  'Filters the exercise library and picker, and flags routine exercises that need something you don’t have in the active profile.': 'Filtruje bibliotekę ćwiczeń i wybór ćwiczeń oraz oznacza w planach treningowych ćwiczenia, które wymagają czegoś, czego nie masz w aktywnym profilu.',

