  '{0} new personal records.': { one: '{0} nowy rekord życiowy.', few: '{0} nowe rekordy życiowe.', many: '{0} nowych rekordów życiowych.', other: '{0} nowych rekordów życiowych.' },
  '{0} minutes is long. Rest periods may be creeping up.': { one: '{0} minuta to długo. Przerwy mogą się wydłużać.', few: '{0} minuty to długo. Przerwy mogą się wydłużać.', many: '{0} minut to długo. Przerwy mogą się wydłużać.', other: '{0} minut to długo. Przerwy mogą się wydłużać.' },
  'Top sets logged without an effort rating; add RIR so the next review can read how hard they were.': 'Główne serie bez oceny wysiłku; dodaj RIR, żeby następny przegląd wiedział, jak były ciężkie.',
  'Add the next load step on the main lift.': 'Dodaj kolejny stopień obciążenia w głównym boju.',
  'Repeat the same loads and get every set.': 'Powtórz te same ciężary i zalicz każdą serię.',
  'Keep the session under an hour and a quarter.': 'Trzymaj sesję poniżej godziny i kwadransa.',
  'A clean session: everything on the sheet got done and the loads held. This is exactly what progress looks like from the inside: unremarkable, repeated.': 'Czysta sesja: wszystko z planu zrobione, ciężary utrzymane. Tak właśnie wygląda postęp od środka: niepozornie i powtarzalnie.',
  'Most of the work got done. One or two sets fell short, which is fine once. It only becomes a signal if the same sets miss next time.': 'Większość roboty zrobiona. Jedna czy dwie serie nie wyszły, raz to nic. Sygnałem staje się to dopiero, jeśli te same serie nie wyjdą następnym razem.',
