  'Sync now': 'Synchronizuj teraz',
  'Your changes are kept here, and merged into your account once it is paired again.': 'Twoje zmiany zostają tutaj i zostaną scalone z twoim kontem, gdy telefon zostanie ponownie sparowany.',
  'Your changes are kept here, and merged into your account once you are signed in again.': 'Twoje zmiany zostają tutaj i zostaną scalone z twoim kontem, gdy znów się zalogujesz.',
  'Changes kept for {0}': 'Zmiany zachowane dla {0}',
