  'Photo, GIF or video': 'Zdjęcie, GIF lub wideo',
  'Optional. A picture makes it easier to spot in a list.': 'Opcjonalnie. Ze zdjęciem łatwiej je wypatrzyć na liście.',
  'Add': 'Dodaj',
  'Change': 'Zmień',
  'Video or guide link (optional)': 'Link do filmu lub poradnika (opcjonalnie)',
