  'Watch video': 'Obejrzyj film',
  'Open link': 'Otwórz link',
  'Plays from YouTube, and only once you tap': 'Odtwarza z YouTube, i to dopiero po stuknięciu',
  'Opens in YouTube': 'Otwiera się w YouTube',
  'That file type isn’t supported. Use a photo, a GIF, or an MP4, MOV or WebM video.': 'Ten typ pliku nie jest obsługiwany. Użyj zdjęcia, GIF-a albo filmu MP4, MOV lub WebM.',
  'That file is too big. Max {0} MB.': 'Ten plik jest za duży. Maksymalnie {0} MB.',
  'That video is too long. Max {0} seconds.': 'Ten film jest za długi. Maksymalnie {0} sekund.',
  'That photo is too large to process on this device.': 'To zdjęcie jest za duże, by przetworzyć je na tym urządzeniu.',
  'You’re offline. Try again once you’re back online.': 'Jesteś offline. Spróbuj ponownie, gdy wróci internet.',
  'This browser cannot read that file.': 'Ta przeglądarka nie może odczytać tego pliku.',
  'There is no room left on this device for that file.': 'Na tym urządzeniu nie ma już miejsca na ten plik.',
  'This video may not play on every device. MP4 (H.264) plays everywhere.': 'Ten film może nie działać na każdym urządzeniu. MP4 (H.264) działa wszędzie.',
  'Your photo and video space on the server is full ({0} of {1} MB).': 'Twoje miejsce na zdjęcia i filmy na serwerze jest pełne ({0} z {1} MB).',
  'The server refused the file as too large.': 'Serwer odrzucił plik jako zbyt duży.',
  'Kept on this device only. Export with photos & videos keeps a copy.': 'Zapisane tylko na tym urządzeniu. Eksport ze zdjęciami i filmami zachowuje kopię.',
  'Your server does not store photos and videos yet.': 'Twój serwer nie przechowuje jeszcze zdjęć i filmów.',
