  '{0} files could not be included': { one: 'Nie udało się dołączyć {0} pliku', few: 'Nie udało się dołączyć plików: {0}', many: 'Nie udało się dołączyć plików: {0}' },
  '{0} file could not be included': 'Nie udało się dołączyć {0} pliku',
  'Without photos and videos': 'Bez zdjęć i filmów',
  'Name it and pick a body part. It works just like any other exercise.': 'Nadaj nazwę i wybierz partię ciała. Działa jak każde inne ćwiczenie.',
  'name + body part, and a photo or video if you like': 'nazwa + partia ciała, a do tego zdjęcie lub film, jeśli chcesz',
  '{0} photos or videos have not reached your server yet.': { one: 'Zdjęcie lub film, którego jeszcze nie ma na twoim serwerze: {0}.', few: 'Zdjęcia lub filmy, które nie dotarły jeszcze na twój serwer: {0}.', many: 'Zdjęcia lub filmy, które nie dotarły jeszcze na twój serwer: {0}.' },
  '{0} photo or video has not reached your server yet.': 'Zdjęcie lub film, którego jeszcze nie ma na twoim serwerze: {0}.',
