  'Its photo or video is deleted with it.': 'Jego zdjęcie lub film też zostanie usunięte.',
  'Its {0} photos or videos are deleted with it.': { one: 'Zdjęcie lub film ({0}) też zostanie usunięte.', few: 'Zdjęcia lub filmy ({0}) też zostaną usunięte.', many: 'Zdjęcia lub filmy ({0}) też zostaną usunięte.' },
  'Its photo or video moves to the new workout.': 'Zdjęcie lub film przejdzie do nowego treningu.',
  'Its {0} photos or videos move to the new workout.': { one: 'Zdjęcie lub film ({0}) przejdzie do nowego treningu.', few: 'Zdjęcia lub filmy ({0}) przejdą do nowego treningu.', many: 'Zdjęcia lub filmy ({0}) przejdą do nowego treningu.' },
  'The server has 1 workout that is not in this backup, logged since it was made or on another device. Replacing deletes it.': 'Na serwerze jest 1 trening, którego nie ma w tej kopii, zapisany później lub na innym urządzeniu. Zastąpienie danych go usunie.',
  'The server has {0} workouts that are not in this backup, logged since it was made or on another device. Replacing deletes them.': { one: 'Na serwerze jest {0} trening, których nie ma w tej kopii, zapisany później lub na innym urządzeniu. Zastąpienie danych go usunie.', few: 'Na serwerze są {0} treningi, których nie ma w tej kopii, zapisane później lub na innym urządzeniu. Zastąpienie danych je usunie.', many: 'Na serwerze jest {0} treningów, których nie ma w tej kopii, zapisanych później lub na innym urządzeniu. Zastąpienie danych je usunie.', other: 'Na serwerze jest {0} treningów, których nie ma w tej kopii, zapisanych później lub na innym urządzeniu. Zastąpienie danych je usunie.' },
