  // --- AI Coach: why a job failed or was refused (lib/coach-api.js JOB_ERRORS, BYOK_ERRORS) ---
  'The Coach isn’t set up on this instance.': 'Trener nie jest skonfigurowany na tej instancji.',
  'The Coach is taking a rest day. Try again tomorrow.': 'Trener ma dziś dzień wolny. Spróbuj ponownie jutro.',
  'The Coach took too long and gave up.': 'Trener myślał zbyt długo i zrezygnował.',
  'The Coach couldn’t sign in to its provider. The instance owner needs to check its setup.': 'Trener nie mógł zalogować się u swojego dostawcy. Właściciel instancji musi sprawdzić konfigurację.',
  'The Coach isn’t installed properly on this instance.': 'Trener nie jest poprawnie zainstalowany na tej instancji.',
  'The Coach couldn’t run. The instance owner needs to check its setup.': 'Nie udało się uruchomić Trenera. Właściciel instancji musi sprawdzić konfigurację.',
  'The Coach hit its AI provider’s limit. Try again later, or the instance owner needs to check the plan or key.': 'Trener dobił do limitu swojego dostawcy AI. Spróbuj później, a jeśli to nie pomoże, właściciel instancji musi sprawdzić plan lub klucz.',
  'The Coach’s AI provider rejected the request format. The instance owner needs to try another model.': 'Dostawca AI Trenera odrzucił format zapytania. Właściciel instancji musi spróbować innego modelu.',
  'The Coach’s AI provider is having an outage. Try again in a little while.': 'Dostawca AI Trenera ma awarię. Spróbuj ponownie za chwilę.',
  'The Coach couldn’t reach its AI provider. The instance owner needs to check the endpoint and the network.': 'Trener nie mógł połączyć się z dostawcą AI. Właściciel instancji musi sprawdzić endpoint i sieć.',
  'The Coach answered with something the app couldn’t use.': 'Trener odpowiedział czymś, czego aplikacja nie może użyć.',
  'The server restarted while the Coach was thinking.': 'Serwer uruchomił się ponownie, gdy Trener myślał.',
  'The Coach couldn’t read your training data.': 'Trener nie mógł odczytać twoich danych treningowych.',
  'The Coach is switched off on this instance for safety reasons.': 'Trener jest wyłączony na tej instancji ze względów bezpieczeństwa.',
  'Something went wrong on the server.': 'Coś poszło nie tak na serwerze.',
  'Your AI provider rejected the key on this phone. Check it under Settings → AI Coach.': 'Twój dostawca AI odrzucił klucz z tego telefonu. Sprawdź go w Ustawieniach → Trener AI.',
  'The Coach isn’t set up on this phone. Check Settings → AI Coach.': 'Trener nie jest skonfigurowany na tym telefonie. Zajrzyj do Ustawień → Trener AI.',
  'Your AI provider couldn’t answer.': 'Twój dostawca AI nie mógł odpowiedzieć.',
  'Something went wrong on this phone.': 'Coś poszło nie tak na tym telefonie.',
