  'Use default folder': 'Użyj domyślnego folderu',
  'This folder can’t be used for backups.': 'Tego folderu nie można użyć do kopii zapasowych.',
  'openGym can no longer write to “{0}”, so copies go to Documents/openGym again. Choose the folder again to switch back.': 'openGym nie może już zapisywać w „{0}”, więc kopie znów trafiają do Documents/openGym. Wybierz folder ponownie, aby do niego wrócić.',
  'openGym can no longer write to the chosen folder, so copies go to Documents/openGym again. Choose the folder again to switch back.': 'openGym nie może już zapisywać w wybranym folderze, więc kopie znów trafiają do Documents/openGym. Wybierz folder ponownie, aby do niego wrócić.',
  // --- missed-workout nudge (lib/nudge.js; the push copy is mirrored in api/nudge-copy.js) ---
  'Nudge me when I skip a planned workout': 'Szturchnij mnie, gdy opuszczę zaplanowany trening',
  'Nudge tone': 'Ton szturchnięcia',
  'Friendly': 'Przyjazny',
  'Guilt trip': 'Wyrzuty sumienia',
  'Drill sergeant': 'Sierżant musztry',
  'One nudge in the evening of a planned day with nothing logged, between 20:00 and 21:30. After 3 missed days in a row it goes quiet until your next workout.': 'Jedno szturchnięcie wieczorem w zaplanowany dzień bez zapisanego treningu, między 20:00 a 21:30. Po 3 opuszczonych dniach z rzędu milknie aż do twojego następnego treningu.',
  'Logged a workout on another device? Before the nudge goes out, the phone checks with your server whenever it lets the app run in the background. Opening the app always catches up.': 'Trening zapisany na innym urządzeniu? Przed szturchnięciem telefon sprawdza to na Twoim serwerze, o ile pozwala aplikacji działać w tle. Otwarcie aplikacji zawsze wszystko aktualizuje.',
  'Everything okay?': 'Wszystko w porządku?',
  '{0} is still waiting. What’s up?': 'Trening „{0}” wciąż czeka. Co się dzieje?',
  'No {0} today? Even a short session tomorrow counts.': 'Dziś bez treningu „{0}”? Jutro nawet krótka sesja się liczy.',
  'Rough day? {0} will keep. Tomorrow is a fresh start.': 'Ciężki dzień? Trening „{0}” poczeka. Jutro nowy start.',
  'Hey, {0} didn’t happen today. All good?': 'Hej, trening „{0}” dziś nie wyszedł. Wszystko dobrze?',
  'I miss you': 'Tęsknię za tobą',
  '{0} waited by the door all evening. For you.': 'Trening „{0}” czekał na ciebie przy drzwiach cały wieczór. Właśnie na ciebie.',
  'The barbell asked about you today. I didn’t know what to say.': 'Sztanga pytała dziś o ciebie. Nie wiedziałem, co powiedzieć.',
  'Was it something I said? {0} misses you.': 'Czy to przez coś, co powiedziałem? Trening „{0}” tęskni za tobą.',
  'I saved you a spot on the bench. It’s still empty.': 'Zająłem ci miejsce na ławce. Wciąż jest puste.',
  'Attention, recruit!': 'Baczność, rekrucie!',
  'Your gains are packing their bags. {0} tomorrow, no excuses!': 'Twoje postępy pakują walizki. Jutro „{0}”, bez wymówek!',
  '{0} doesn’t do itself, recruit. Move it!': 'Trening „{0}” sam się nie zrobi, rekrucie. Ruszaj się!',
  'Excuses don’t lift weights. Report for {0} tomorrow!': 'Wymówki nie podnoszą ciężarów. Jutro meldujesz się na „{0}”!',
  'Your muscles filed a missing-person report. Show up for {0}!': 'Twoje mięśnie zgłosiły twoje zaginięcie. Stawić się na „{0}”!',
  'That address answers, but it isn’t an openGym server. Check the URL.': 'Ten adres odpowiada, ale to nie jest serwer openGym. Sprawdź URL.',
  'That address answers, but a login page or proxy rule replied instead of openGym. Let /api/ through to openGym unchanged. See “Phone app and CORS” in docs/SELF_HOSTING.md.': 'Ten adres odpowiada, ale zamiast openGym odpowiedziała strona logowania albo reguła proxy. Przepuść /api/ do openGym bez zmian. Zobacz “Phone app and CORS” w docs/SELF_HOSTING.md.',
  'Switch sides': 'Zmień stronę',
  'Saves a dated copy to “{0}” after finishing a workout or editing a routine, and keeps the newest {1}.': 'Zapisuje kopię z datą w „{0}” po każdym zakończonym treningu lub edycji planu i trzyma {1} najnowszych.',
  'Saves a dated copy to the folder you chose after finishing a workout or editing a routine, and keeps the newest {0}.': 'Zapisuje kopię z datą w wybranym folderze po każdym zakończonym treningu lub edycji planu i trzyma {0} najnowszych.',
