  '{0} routine was made on this device while signed out. Add it to your profile, or keep the profile exactly as it is on the server.': '{0} plan treningowy powstał na tym urządzeniu bez logowania. Dodaj go do profilu albo zostaw profil dokładnie taki, jaki jest na serwerze.',
