  'Allow': 'Zezwól',
  'Allowed {0}': 'Zezwolono {0}',
  'Anything you type to the Coach': 'Wszystko, co piszesz do Trenera',
  'Change your mind anytime under AI data sharing in the Coach menu.': 'Zdanie możesz zmienić w każdej chwili w menu Trenera, w sekcji Udostępnianie danych AI.',
  'Nothing allowed yet': 'Jeszcze nic nie zezwolono',
