  'Send your training to {0}?': 'Wysłać twój trening do {0}?',
  'The Coach asks before anything leaves.': 'Trener pyta, zanim cokolwiek wyjdzie.',
  'Through your server': 'Przez twój serwer',
  'To answer, the Coach sends this through your openGym server to {0}, an AI service outside openGym that your server’s admin picked:': 'Żeby odpowiedzieć, Trener wysyła to przez twój serwer openGym do {0}, usługi AI spoza openGym wybranej przez admina twojego serwera:',
  'To answer, this device sends this straight to {0}, an AI service outside openGym, with your API key:': 'Żeby odpowiedzieć, to urządzenie wysyła to bezpośrednio do {0}, usługi AI spoza openGym, z twoim kluczem API:',
  'Who may see your training': 'Kto może widzieć twój trening',
  'Who the Coach may send your training to from this device. Withdraw it and the Coach asks again next time. A model on your own network never needs asking.': 'Komu Trener może wysyłać twój trening z tego urządzenia. Jeśli cofniesz zgodę, Trener zapyta ponownie następnym razem. Model w twojej własnej sieci nigdy nie musi pytać.',
  'With your API key': 'Z twoim kluczem API',
  'Withdraw': 'Cofnij zgodę',
  'Withdrawn. The Coach will ask before it sends anything again.': 'Zgoda cofnięta. Trener zapyta, zanim znowu coś wyśle.',
  'Your answers to the Coach: goal, days, equipment, limits and injuries': 'Twoje odpowiedzi dla Trenera: cel, dni, sprzęt, ograniczenia i kontuzje',
  'Your body weight and goal weight': 'Twoja masa ciała i waga docelowa',
  'Your data, your call': 'Twoje dane, twoja decyzja',
  'Your name, email and sign-in stay put. {0} handles the rest under its own privacy terms.': 'Imię, e-mail i logowanie zostają tutaj. {0} przetwarza resztę według własnych zasad prywatności.',
  'Your plan: routines, exercises, sets, reps and schedule': 'Twój plan: rutyny, ćwiczenia, serie, powtórzenia i harmonogram',
  'Your unit and language': 'Twoja jednostka i język',
  'Your workouts: weights, reps, times, effort and session notes': 'Twoje treningi: ciężary, powtórzenia, czasy, wysiłek i notatki z sesji',
  // --- delete my account (App Store rule 5.1.1(v)) ---
  'Delete my account': 'Usuń moje konto',
  'Removes your profile and everything in it from this server.': 'Usuwa Twój profil i wszystko, co w nim jest, z tego serwera.',
  'Delete your account?': 'Usunąć konto?',
  'Your profile, workouts, body weight, photos and videos are deleted from this server for good. There is no undo, and not even your admin can bring them back.': 'Twój profil, treningi, masa ciała, zdjęcia i filmy zostaną usunięte z tego serwera na zawsze. Nie da się tego cofnąć, nawet Twój administrator ich nie odzyska.',
  'Want a copy first? Export a backup. You can import it into openGym anytime.': 'Najpierw kopia? Wyeksportuj kopię zapasową. Możesz ją zaimportować do openGym w każdej chwili.',
  'Type {0} to confirm.': 'Wpisz {0}, aby potwierdzić.',
  'Account name': 'Nazwa konta',
  'Delete forever': 'Usuń na zawsze',
  'That is not your account name.': 'To nie jest nazwa Twojego konta.',
  'You’re the only admin here, and other profiles still use this server. Make someone else an admin first.': 'Jesteś tu jedynym administratorem, a inne profile wciąż korzystają z tego serwera. Najpierw zrób administratorem kogoś innego.',
  'Couldn’t delete the account. Nothing was removed.': 'Nie udało się usunąć konta. Nic nie zostało usunięte.',
  'Your account is gone. Thanks for every rep.': 'Twojego konta już nie ma. Dzięki za każde powtórzenie.',
  'Confirm it’s you to delete your openGym account': 'Potwierdź, że to Ty, aby usunąć konto openGym',
  'Not confirmed on this phone. Nothing was deleted.': 'Nie potwierdzono na tym telefonie. Nic nie zostało usunięte.',
  'This phone has no screen lock, so the name you typed is the only check.': 'Ten telefon nie ma blokady ekranu, więc wpisana nazwa to jedyne sprawdzenie.',
  'Your phone checks that it’s you (face, fingerprint or passcode), then the account is deleted.': 'Telefon sprawdzi, czy to Ty (twarz, odcisk palca lub kod), a potem konto zostanie usunięte.',
