  'Open Apple Health': 'Otwórz Apple Zdrowie',
  'Workouts and weigh-ins go to Apple Health when you finish or change them.': 'Treningi i pomiary wagi trafiają do Apple Zdrowie, gdy je kończysz lub zmieniasz.',
  'Writing to Apple Health': 'Zapisywanie w Apple Zdrowie',
  'Apple Health permission not granted': 'Nie przyznano uprawnienia Apple Zdrowie',
