  'Stop writing to Apple Health?': 'Przestać zapisywać w Apple Zdrowie?',
  'What openGym already wrote can stay in Apple Health as your data, or be removed from it.': 'To, co openGym już zapisał, może zostać w Apple Zdrowie jako twoje dane albo zostać usunięte.',
  'Your workouts in Apple Health': 'Twoje treningi w Apple Zdrowie',
