  "Weekly rate": "Tempo tygodniowe",
  "Trend {0} a week ({1})": "Trend {0} tygodniowo ({1})",
  "A few more weigh-ins, spread over the next days, and you get a weekly trend.": "Jeszcze kilka ważeń w ciągu najbliższych dni i zobaczysz tygodniowy trend.",
  "On pace": "W tempie",
  "Slower than planned": "Wolniej niż w planie",
