  "Enter a range first": "Najpierw podaj zakres",
  "The trend through your weigh-ins of the last 3 weeks, so one salty dinner does not move it. Give it a range and the card tells you whether you are on pace.": "Trend z twoich ważeń z ostatnich 3 tygodni, więc jedna słona kolacja go nie ruszy. Podaj zakres, a karta powie ci, czy jesteś w tempie.",
