  "Hold within ±{0} a week.": "Utrzymać się w granicach ±{0} tygodniowo.",
  "Lose {0} to {1} a week.": "Chudnąć od {0} do {1} tygodniowo.",
  "Gain {0} to {1} a week.": "Przybierać od {0} do {1} tygodniowo.",
  "A cut is often 0.5 to 1 % a week, a lean bulk 0.25 to 0.5 %.": "Redukcja to często 0,5 do 1 % tygodniowo, czysta masa 0,25 do 0,5 %.",
  "Remove range": "Usuń zakres",
  'Admin': 'Admin',
  'Heaviest set as a share of body weight, per workout': 'Najcięższa seria jako odsetek masy ciała, na trening',
  'Estimated 1RM as a share of body weight, per workout': 'Szacowane 1RM jako odsetek masy ciała, na trening',
  'Body weight over this period: {0} → {1}. Bodyweight and assisted exercises count your body weight as part of the load.': 'Masa ciała w tym okresie: {0} → {1}. W ćwiczeniach z masą ciała i wspomaganych Twoja masa ciała liczy się jako część obciążenia.',
  'Weight stack': 'Stos obciążenia',
  'The weights this machine really has, odd steps and all. Progression, deloads, warm-ups and the + and − buttons land only on these.': 'Ciężary, które ta maszyna naprawdę ma, z dziwnymi skokami włącznie. Progresja, deloady, rozgrzewki i przyciski + i − trafiają tylko na nie.',
  'No list yet, so this exercise steps by its increment as usual.': 'Jeszcze bez listy, więc to ćwiczenie rośnie o swój krok, jak zwykle.',
  'First ({0})': 'Pierwszy ({0})',
  'How many': 'Ile',
  'Fill in': 'Wypełnij',
  'That’s the whole stack: {0} {1} is the heaviest it goes, so the weight stays.': 'To cały stos: {0} {1} to najwięcej, więc ciężar zostaje.',
  'No code on your phone? It only has one while it’s connected to this server: Settings → Account → Connect to my server.': 'Nie ma kodu na telefonie? Pojawia się tylko, gdy telefon jest połączony z tym serwerem: Ustawienia → Konto → Połącz z moim serwerem.',
  'Signing in on your computer too needs your own server. Connect this phone to it, and Add another device then gives the computer a code.': 'Żeby logować się też na komputerze, potrzebujesz własnego serwera. Połącz z nim ten telefon, a Dodaj kolejne urządzenie da komputerowi kod.',
  'How hard it felt': 'Jak ciężko było',
  'Not rated yet': 'Jeszcze bez oceny',
  'How hard did that feel?': 'Jak ciężko to było?',
  'Tap how it felt, or type an exact {0}.': 'Stuknij, jak było, albo wpisz dokładne {0}.',
  'All out, nothing left': 'Na maksa, nic nie zostało',
  'Nearly all out': 'Prawie na maksa',
  'Very hard, one word at a time': 'Bardzo ciężko, pojedyncze słowa',
  'Hard, short sentences only': 'Ciężko, tylko krótkie zdania',
  'Working, but steady': 'Wysiłek, ale równo',
  'Easy, you could chat the whole way': 'Lekko, dałoby się gadać całą drogę',
  'I own no dumbbells': 'Nie mam hantli',
  'Dumbbell lifts stay out of the library, the picker and the Coach’s plans.': 'Ćwiczenia z hantlami znikają z biblioteki, wyboru i planów Trenera.',
  'Everything but dumbbells': 'Wszystko oprócz hantli',
  'None, so dumbbell lifts stay hidden.': 'Brak, więc ćwiczenia z hantlami są ukryte.',
  'openGym reads only while it is open: heart rate for workouts of the last day, weigh-ins of the last year. Older workouts stay as they are.': 'openGym czyta tylko, gdy jest otwarty: tętno z treningów z ostatniej doby, pomiary wagi z ostatniego roku. Starsze treningi zostają bez zmian.',
  // --- seasonal themes (lib/seasonal.js) ---
  'Also during workouts': 'Także podczas treningu',
  'A cobweb in the header, bats behind the rest timer, pumpkins on the finish screen. Never on your sets.': 'Pajęczyna w nagłówku, nietoperze za minutnikiem przerwy, dynie na podsumowaniu. Nigdy na Twoich seriach.',
  'Seasonal themes': 'Motywy sezonowe',
  'Little extras for the time of year.': 'Drobne dodatki na tę porę roku.',
  'Halloween': 'Halloween',
  'Auto': 'Auto',
  'Spooky colors': 'Straszne kolory',
  'A pumpkin orange accent while Halloween shows. Your own color comes back after.': 'Dyniowy pomarańczowy akcent, dopóki trwa Halloween. Potem wraca Twój kolor.',
  'Spiders, bats and one shy pumpkin until the end of October. Never during a workout.': 'Pająki, nietoperze i jedna nieśmiała dynia do końca października. Nigdy podczas treningu.',
  'Back next October. The spiders are on holiday.': 'Wróci w przyszłym październiku. Pająki są na urlopie.',
  'On all year round. Bold choice.': 'Włączone cały rok. Odważnie.',
  'Off, even in season. Fair enough.': 'Wyłączone, nawet w sezonie. W porządku.',
  'Boo! You found the pumpkin. It was watching you train.': 'Bu! Jest dynia! Patrzyła, jak trenujesz.',
  'Boo! Pumpkin found. Your next PR is now officially haunted.': 'Bu! Dynia znaleziona. Twój następny rekord jest teraz oficjalnie nawiedzony.',
  'Boo! The bats were not part of the warm-up.': 'Bu! Nietoperze nie były częścią rozgrzewki.',
  'Boo! Found it. The spiders owe you a rep.': 'Bu! Mam ją. Pająki są Ci winne jedno powtórzenie.',
  'The pumpkin is napping. Come back tomorrow.': 'Dynia ucina sobie drzemkę. Wróć jutro.',
  // --- Christmas theme and advent calendar (seasonal/christmas.jsx, seasonal/advent-doors.js) ---
  'That one is unwrapped. A new present turns up tomorrow.': 'Ten prezent jest już rozpakowany. Jutro pojawi się nowy.',
  'Festive icon on. Very fetching.': 'Świąteczna ikona włączona. Pięknie Ci w niej.',
  'Fancy a festive icon?': 'Masz ochotę na świąteczną ikonę?',
  'The barbell has put on its Santa hat. Just for this phone, and you can switch back in Settings any time.': 'Sztanga włożyła czapkę Mikołaja. Tylko na tym telefonie, a w Ustawieniach możesz w każdej chwili wrócić do poprzedniej.',
  'Try it': 'Wypróbuj',
  'Door {0} is waiting for you': 'Okienko {0} na Ciebie czeka',
  'Door {0} is still waiting': 'Okienko {0} wciąż czeka',
  'All 24 doors open. Merry everything!': 'Wszystkie 24 okienka otwarte. Wesołych Świąt!',
  'All caught up. See you tomorrow!': 'Wszystko nadrobione. Do jutra!',
  'Advent calendar': 'Kalendarz adwentowy',
  '{0} of 24 doors open': 'Otwarte okienka: {0} z 24',
  'No peeking 👀': 'Nie podglądaj 👀',
  'One door a day until the 24th. Missed one? It waits for you.': 'Jedno okienko dziennie do 24. Ominęło Cię któreś? Poczeka.',
  'Door {0}, locked': 'Okienko {0}, zamknięte',
  'Door {0}, open': 'Okienko {0}, otwarte',
