  'Strength block, 4 weeks': 'Blok siłowy, 4 tygodnie',
  'The schedule in your plan right now becomes this programme’s.': 'Harmonogram, który teraz ma twój plan, staje się harmonogramem tego programu.',
  'The week is the calendar week: week 1 is the one you start in. A pause holds it.': 'Tydzień to tydzień kalendarzowy: tydzień 1 to ten, w którym zaczynasz. Pauza go wstrzymuje.',
  'This programme is gone.': 'Tego programu już nie ma.',
  'Three days of plain linear progression, with a deload every fourth week.': 'Trzy dni zwykłej progresji liniowej, z deloadem co czwarty tydzień.',
  'Three days on the 5×5 routines, a little heavier every week, then a light week to bounce back.': 'Trzy dni na planach 5×5, co tydzień trochę ciężej, potem lżejszy tydzień na regenerację.',
  'Upper / lower by effort, 6 weeks': 'Góra / dół według wysiłku, 6 tygodni',
  'Use my current plan': 'Użyj mojego obecnego planu',
  'Week 1 starts now. Have fun!': 'Tydzień 1 zaczyna się teraz. Baw się dobrze!',
