  "Your watch or scale writes here too? Garmin, COROS, Fitbit, Withings, Oura and friends reach openGym this way.": "Twój zegarek lub waga też tu zapisuje? Garmin, COROS, Fitbit, Withings, Oura i spółka trafiają do openGym właśnie tak.",
  "Now in Integrations": "Teraz w Integracjach",
