  "Heart rate from your watch fills in each set.": "Tętno z zegarka trafia do każdej serii.",
  "Weigh-ins from your smart scale land here.": "Ważenia z inteligentnej wagi trafiają tutaj.",
  "Finished workouts and weigh-ins go to Health Connect.": "Ukończone treningi i ważenia trafiają do Health Connect.",
  "Bring your Hevy history over with a Pro API key.": "Przenieś historię z Hevy kluczem API Pro.",
  "Workouts, routines and weigh-ins, once.": "Treningi, rutyny i ważenia, jednorazowo.",
