  "Reads the export file of another app, once.": "Czyta plik eksportu innej aplikacji, jednorazowo.",
  "Exercises are matched to the library, you check the rest.": "Ćwiczenia są dopasowywane do biblioteki, resztę sprawdzasz ty.",
  "Spreadsheet (CSV)": "Arkusz (CSV)",
  "Every set, weigh-in and measurement, for Excel and friends.": "Każda seria, ważenie i pomiar, dla Excela i spółki.",
  "One row per set, plus body weight and measurements.": "Jeden wiersz na serię, plus masa ciała i pomiary.",
  "openGym can read it back in later.": "openGym może go później wczytać z powrotem.",
  "Tell Home Assistant, n8n or ntfy when you finish a workout.": "Daj znać Home Assistant, n8n lub ntfy, gdy kończysz trening.",
