  "Built from your work weight and rounded to this gym’s plates and dumbbells. An exercise can pick its own in its settings.": "Liczone od ciężaru roboczego i zaokrąglane do talerzy i hantli tej siłowni. Ćwiczenie może mieć własne w swoich ustawieniach.",
