  "Something else": "Coś innego",
  "Squats, presses, rows and friends get a ramp. Curls and raises start cold.": "Przysiady, wyciskania, wiosłowania i spółka dostają rampę. Uginania i wznosy startują na zimno.",
  "Straight into the work sets.": "Od razu do serii roboczych.",
  "That workout is over, so these can’t be applied any more.": "Ten trening się skończył, więc nie da się już tego zastosować.",
  "The app ramps up from your work weight: more warm-up sets when it is heavy, fewer when it is light, on your gym’s plates.": "Aplikacja buduje rozgrzewkę od ciężaru roboczego: więcej serii przy ciężkim, mniej przy lekkim, na talerzach twojej siłowni.",
  "The rack is taken, so do it at the end. The rest of the session does not need it.": "Stojak zajęty, więc zrób to na koniec. Reszta treningu go nie potrzebuje.",
  "There’s no workout running.": "Żaden trening nie trwa.",
  "These warm-ups come before the work sets every session, as a share of the work weight, so they grow with it.": "Ta rozgrzewka idzie przed seriami roboczymi na każdym treningu, jako część ciężaru roboczego, więc rośnie razem z nim.",
  "This is the demo, so there is no AI model behind me. On your own server I read your session and suggest changes like these.": "To jest demo, więc nie stoi za mną model AI. Na twoim serwerze czytam trening i proponuję takie zmiany.",
