  "Frame your best side": "Pokaż swoją lepszą stronę",
  "Only you see it, and it stays on this device.": "Widzisz je tylko ty i zostaje na tym urządzeniu.",
  "Only you see it, here and on your other devices. Not even an admin can.": "Widzisz je tylko ty, tutaj i na innych swoich urządzeniach. Nawet admin nie.",
  "Photo crop. Arrow keys move it, plus and minus zoom.": "Kadrowanie zdjęcia. Strzałki przesuwają, plus i minus przybliżają.",
  "Picture removed. Back to the letter.": "Zdjęcie usunięte. Wraca litera.",
  "Picture set. Looking sharp.": "Zdjęcie ustawione. Wyglądasz świetnie.",
  "Profile picture": "Zdjęcie profilowe",
  "Remove picture": "Usuń zdjęcie",
  "That isn’t a photo. Try a JPEG, PNG, WebP or HEIC.": "To nie jest zdjęcie. Spróbuj JPEG, PNG, WebP lub HEIC.",
  "Use this photo": "Użyj tego zdjęcia",
  "Zoom": "Powiększenie",
  "Missed plan": "Plan opuszczony",
  "Open this day": "Otwórz ten dzień",
  "Planned, not trained. Any other day this week still counts.": "Zaplanowane, bez treningu. Każdy inny dzień tego tygodnia wciąż się liczy.",
  "Planned, not trained. Any workout that week would have counted.": "Zaplanowane, bez treningu. Każdy trening w tamtym tygodniu by się liczył.",
  "Planned, not trained. No harm done: you trained another day that week, so it still counts.": "Zaplanowane, bez treningu. Nic się nie stało: trenowałeś innego dnia, więc tydzień i tak się liczy.",
  "Bank 1 freeze, earned every 4 trained weeks. Two missed weeks in a row end the streak.": "1 zamrożenie w zapasie, co 4 tygodnie z treningiem. Dwa opuszczone tygodnie z rzędu kończą serię.",
  "Bank up to 2 freezes, one every 4 trained weeks. Even two missed weeks in a row can be covered.": "Do 2 zamrożeń w zapasie, jedno co 4 tygodnie z treningiem. Nawet dwa opuszczone tygodnie z rzędu da się pokryć.",
  "Change the freeze rule": "Zmień zasadę zamrożeń",
  "Every 4th week you train earns a freeze. You can bank 1.": "Co 4. tydzień z treningiem daje zamrożenie. Możesz mieć 1.",
  "Every week counts. Miss one and the streak starts over.": "Każdy tydzień się liczy. Opuścisz jeden i seria zaczyna się od nowa.",
  "From now on: {0}.": "Od teraz: {0}.",
  "From the week of {0} on: {1}.": "Od tygodnia {0}: {1}.",
  "Generous": "Hojna",
  "Gentle": "Łagodna",
  "How forgiving should your week streak be?": "Jak wyrozumiała ma być twoja seria tygodni?",
  "How strict should your streak be?": "Jak surowa ma być twoja seria?",
  "Miss a week and a freeze covers it: the streak keeps going, that week just adds nothing. Two missed weeks in a row, and it starts over.": "Opuścisz tydzień? Zamrożenie go pokryje: seria trwa dalej, ten tydzień po prostu nic nie dodaje. Dwa opuszczone tygodnie z rzędu, i zaczyna się od nowa.",
  "No freezes": "Bez zamrożeń",
  "No freezes on your rule. Every week counts.": "Twoja zasada nie ma zamrożeń. Każdy tydzień się liczy.",
  "No freezes on your rule: a week without a workout starts it over.": "Twoja zasada nie ma zamrożeń: tydzień bez treningu i seria zaczyna się od nowa.",
  "No workout, and your rule has no freezes, so the streak started over.": "Bez treningu, a twoja zasada nie ma zamrożeń, więc seria zaczęła się od nowa.",
  "Weeks already counted stay as they are.": "Już policzone tygodnie zostają bez zmian.",
  "You can change it later in Settings. A change counts from then on.": "Możesz to później zmienić w Ustawieniach. Zmiana liczy się od tej chwili.",
  "Your rule right now: {0}.": "Twoja zasada teraz: {0}.",
  "Your streak counts weeks with at least one workout. Freezes can cover the odd missed week.": "Seria liczy tygodnie z co najmniej jednym treningiem. Zamrożenia mogą pokryć sporadycznie opuszczony tydzień.",
  "{0} since the week of {1}.": "{0} od tygodnia {1}.",
  "This phone has no print service. Turn one on in its settings and try again.": "Ten telefon nie ma usługi drukowania. Włącz jakąś w ustawieniach i spróbuj ponownie.",
