  "You are letting this trainer see the categories marked here, and change the ones marked suggest or apply. If the trainer works for a gym, its gym lead sees the categories in the gym lead row, never more than view. You can change this or disconnect any time, and it stops working the moment you do. Every look and every change is written to your sharing log, which only you can read.": "Pozwalasz temu trenerowi widzieć zaznaczone tu kategorie i zmieniać te oznaczone jako proponuj lub zastosuj. Jeśli trener pracuje dla siłowni, jej kierownik widzi kategorie z własnego wiersza, nigdy więcej niż podgląd. Możesz to zmienić lub się rozłączyć w każdej chwili, a działanie ustaje w tej samej chwili. Każde zajrzenie i każda zmiana trafia do twojego dziennika udostępniania, który może czytać tylko ty.",
