  "This is public to everyone on this server: everyone with an account here can see it, try it and copy it. Your name and the date go with it, always. Only share what is yours: something you made, recorded or have the right to pass on. The exercise pictures and animations of the built-in library are licensed and can never be shared. You can stop sharing any time; copies people already took stay with them.": "To jest publiczne dla wszystkich na tym serwerze: każdy, kto ma tu konto, może to zobaczyć, wypróbować i skopiować. Twoje imię i data zawsze idą razem z tym. Udostępniaj tylko to, co twoje: coś, co zrobiłeś, nagrałeś albo masz prawo przekazać dalej. Obrazy i animacje ćwiczeń z wbudowanej biblioteki są licencjonowane i nigdy nie można ich udostępniać. Możesz przestać udostępniać w każdej chwili; kopie, które inni już wzięli, zostają u nich.",
