  "Link your {0} account and sign in with it from now on. Your passkeys keep working too. First a quick check that this is really you.": "Połącz konto {0} i loguj się nim od teraz. Twoje klucze dostępu dalej działają. Najpierw szybkie sprawdzenie, że to naprawdę ty.",
  "Linked. You can sign in with {0} from now on.": "Połączone. Od teraz możesz logować się przez {0}.",
  "Linked. {0} signs you in here.": "Połączone. {0} loguje cię tutaj.",
  "Not linked yet.": "Jeszcze niepołączone.",
  "Off to {0}…": "Lecimy do {0}…",
  "Sign in with your provider again first, then try once more.": "Najpierw zaloguj się ponownie u swojego dostawcy, potem spróbuj jeszcze raz.",
  "Sign in with {0}": "Zaloguj się przez {0}",
  "Sign-in cancelled. No harm done.": "Logowanie anulowane. Nic się nie stało.",
  "That sign-in took too long or came from another tab. Give it another go.": "To logowanie trwało za długo albo przyszło z innej karty. Spróbuj jeszcze raz.",
  "That was a different {0} account than the one linked to this profile.": "To było inne konto {0} niż to połączone z tym profilem.",
  "That {0} account is already linked to another profile here.": "To konto {0} jest już tu połączone z innym profilem.",
  "This profile is already linked to a {0} account.": "Ten profil jest już połączony z kontem {0}.",
  "This profile is linked to your {0} account, so signing in there signs you in here.": "Ten profil jest połączony z twoim kontem {0}: zalogowany tam, zalogowany tutaj.",
  "This server is invite-only and {0} alone does not get you in. Ask whoever runs it.": "Ten serwer działa tylko na zaproszenia i samo {0} nie wystarczy. Zapytaj osobę, która go prowadzi.",
  "This server signs everyone in with {0}. New here? Signing in makes your profile.": "Na tym serwerze wszyscy logują się przez {0}. Nowy tutaj? Zalogowanie się utworzy twój profil.",
  "This server signs people in with {0}.": "Ten serwer loguje ludzi przez {0}.",
  "Too many attempts. Try again in a minute.": "Za dużo prób. Spróbuj za minutę.",
  "Unlink": "Rozłącz",
  "Unlinked. {0} no longer signs you in here.": "Rozłączone. {0} już cię tu nie loguje.",
  "or use a pairing code": "albo użyj kodu parowania",
  "{0} could not be reached. Try again in a moment.": "Nie udało się połączyć z {0}. Spróbuj za chwilę.",
  "{0} is the only way into this profile, so it stays linked. Add a passkey first.": "{0} to jedyna droga do tego profilu, więc zostaje połączone. Najpierw dodaj klucz dostępu.",
  "{0} let you in, but this server only takes certain groups. Ask whoever runs it to add you.": "{0} cię wpuścił, ale ten serwer przyjmuje tylko wybrane grupy. Poproś osobę, która go prowadzi, żeby cię dodała.",
  "{0} sent back something we could not verify, so nobody was signed in. If it keeps happening, the admin page shows why.": "{0} odesłał coś, czego nie dało się zweryfikować, więc nikt nie został zalogowany. Jeśli to się powtarza, strona administracji pokazuje dlaczego.",
  "Backups: {0}": "Zamienniki: {0}",
  "Suggested": "Propozycje",
  "Add “{0}” as a backup": "Dodaj „{0}” jako zamiennik",
  "Ask the Coach for a swap": "Zapytaj Coacha o zamiennik",
  "Per gym": "Według siłowni",
  "Separate numbers per gym": "Osobne wyniki dla każdej siłowni",
  "Last time and the next weight come from this gym only.": "Ostatni raz i następny ciężar biorą się tylko z tej siłowni.",
  "Brand at {0}": "Marka w {0}",
  "Life Fitness, Technogym… (optional)": "Life Fitness, Technogym… (opcjonalnie)",
  "Same brand at another gym? It shares these numbers. Records and Stats still count every gym.": "Ta sama marka na innej siłowni? Dzieli te wyniki. Rekordy i statystyki dalej liczą wszystkie siłownie.",
  "For machines and cables that feel different from gym to gym. Free weights rarely need it.": "Dla maszyn i wyciągów, które na każdej siłowni są inne. Wolne ciężary rzadko tego potrzebują.",
  "All gyms": "Wszystkie siłownie",
  "Today’s planned rows for {0} didn’t fit, so the routine’s own are up: {1}": "Zaplanowane serie dla {0} nie pasowały, więc są serie z planu: {1}",
  "Today’s rows come from {0}. Your routine stays as it is.": "Dzisiejsze serie są od {0}. Twój plan zostaje bez zmian.",
  "Today’s rows were planned for this day. Your routine stays as it is.": "Dzisiejsze serie zaplanowano na ten dzień. Twój plan zostaje bez zmian.",
  "Body composition from your scale": "Skład ciała z twojej wagi",
  "Body fat and lean mass, as your scale saved them. Shown under Body measurements, never mixed into what you log.": "Tkanka tłuszczowa i beztłuszczowa masa ciała, tak jak zapisała je twoja waga. Widoczne w Wymiarach ciała, nigdy nie mieszają się z tym, co wpisujesz.",
  "Body fat, lean mass, bone mass, body water and BMR, as your scale saved them. Shown under Body measurements, never mixed into what you log.": "Tkanka tłuszczowa, beztłuszczowa masa ciała, masa kostna, woda w organizmie i podstawowa przemiana materii, tak jak zapisała je twoja waga. Widoczne w Wymiarach ciała, nigdy nie mieszają się z tym, co wpisujesz.",
  "From Health Connect": "Z Health Connect",
