  "Add it as a custom connector in your AI assistant, with a token from below.": "Dodaj go jako własny konektor w asystencie AI, razem z tokenem poniżej.",
  "After a year": "Po roku",
  "After {0} days": "Po {0} dniach",
  "Copy it now: this is the only time openGym shows it. Treat it like a password.": "Skopiuj go teraz: openGym pokazuje go tylko ten jeden raz. Traktuj go jak hasło.",
  "Ends": "Wygasa",
  "Every program using one stops getting in right away.": "Każdy program, który go używa, od razu traci dostęp.",
  "For AI assistants over MCP, planners and scripts. Each sees only what you tick.": "Dla asystentów AI przez MCP, planerów i skryptów. Każdy widzi tylko to, co zaznaczysz.",
