  "Last photo: {0} days ago. Same spot, same light?": { one: "Ostatnie zdjęcie: {0} dzień temu. To samo miejsce, to samo światło?", few: "Ostatnie zdjęcie: {0} dni temu. To samo miejsce, to samo światło?", many: "Ostatnie zdjęcie: {0} dni temu. To samo miejsce, to samo światło?", other: "Ostatnie zdjęcie: {0} dni temu. To samo miejsce, to samo światło?" },
  "A buzz for each phase": "Wibracja dla każdej fazy",
  "A copy of everything, once a day, in a folder of your own: Nextcloud, ownCloud, a NAS, anything that speaks WebDAV. Your server, nobody else’s.": "Kopia wszystkiego raz dziennie w twoim własnym folderze: Nextcloud, ownCloud, NAS albo cokolwiek, co gada po WebDAV. Twój serwer, nikogo innego.",
  "A sound for each kind of rest": "Osobny dźwięk dla każdego rodzaju odpoczynku",
  "A tick on every day you trained, with how many sets. Only you see it, the same as the plan.": "Ptaszek przy każdym dniu z treningiem, z liczbą serii. Widzisz go tylko ty, tak jak plan.",
  "A tone for each phase": "Osobny ton dla każdej fazy",
  "Again": "Jeszcze raz",
  "An app password is best": "Najlepiej hasło aplikacji",
  "Back up every day": "Kopia codziennie",
