  "Backed up to {0}": "Kopia trafiła na {0}",
  "Calendar feed": "Kanał kalendarza",
  "Calendar feed off": "Kanał kalendarza wyłączony",
  "Cardio goes up as what it was: a run, a ride, a row. Strength as Weight Training, with every set in the description.": "Cardio trafia tam jako to, czym było: bieg, jazda, wiosłowanie. Siłówka jako Trening siłowy, z każdą serią w opisie.",
  "Change server or password": "Zmień serwer lub hasło",
  "Check the connection": "Sprawdź połączenie",
  "Connect Strava once from openGym in a browser, signed in to your server. Your workouts then go up from the server, whichever device you log them on.": "Połącz konto Strava raz z openGym w przeglądarce, po zalogowaniu się na swój serwer. Potem treningi wysyła serwer, niezależnie od urządzenia, na którym je zapisujesz.",
  "Connected. Your first backup goes up now.": "Połączono. Pierwsza kopia już leci.",
  "Disconnect Strava?": "Odłączyć konto Strava?",
  "Disconnect WebDAV?": "Odłączyć WebDAV?",
  "Explosive lift (X)": "Wybuchowe podnoszenie (X)",
  "Folder address": "Adres folderu",
  "Get set": "Przygotuj się",
  "Know from your pocket whether to stay put, go back to the top of the superset or move on.": "Wiedz prosto z kieszeni, czy zostać na miejscu, wrócić na początek superserii, czy iść dalej.",
  "Last backup {0}": "Ostatnia kopia {0}",
  "Last fetched by a calendar {0}": "Ostatnio pobrane przez kalendarz {0}",
  "Last upload": "Ostatnie wysłanie",
  "Leave empty to keep the one saved": "Zostaw puste, by zachować zapisane",
  "Like 3-1-1-0: three seconds down, one at the bottom, one up.": "Np. 3-1-1-0: trzy sekundy w dół, jedna na dole, jedna w górę.",
  "Like the exercise ({0})": "Jak w ćwiczeniu ({0})",
  "Link copied. Paste it into your calendar app.": "Link skopiowany. Wklej go w aplikacji kalendarza.",
  "Make a new link": "Utwórz nowy link",
  "Make a new link?": "Utworzyć nowy link?",
  "Make my calendar link": "Utwórz mój link do kalendarza",
  "New link made. The old one is gone.": "Nowy link gotowy. Stary przepadł.",
  "Nextcloud or any WebDAV folder, once a day": "Nextcloud lub dowolny folder WebDAV, raz dziennie",
  "No backup yet": "Brak kopii",
  "No calendar has fetched it yet.": "Żaden kalendarz jeszcze go nie pobrał.",
  "No openGym backups in that folder yet.": "W tym folderze nie ma jeszcze kopii openGym.",
  "No tempo": "Bez tempa",
  "Open in my calendar app": "Otwórz w aplikacji kalendarza",
  "Pick one. You choose whether it replaces what is here or merges with it.": "Wybierz jedną. Ty decydujesz, czy zastąpi to, co tu jest, czy się z tym połączy.",
  "Reconnect": "Połącz ponownie",
  "Rep {0} of {1}": "Powtórzenie {0} z {1}",
  "Restore from a backup": "Przywróć z kopii",
  "Same as the rest ({0})": "Jak pozostałe ({0})",
  "Seconds for each part of a rep: lower, pause, lift, squeeze. 3-1-1-0 is three down, one at the bottom, one up, straight into the next.": "Sekundy na każdą część powtórzenia: opuszczanie, pauza, podnoszenie, spięcie. 3-1-1-0 to trzy w dół, jedna na dole, jedna w górę i od razu następne.",
  "Show finished workouts too": "Pokaż też ukończone treningi",
  "Strava connected. Your next workout goes up by itself.": "Strava połączona. Następny trening wyśle się sam.",
  "Strava disconnected": "Strava odłączona",
  "Strava is listening": "Strava słucha",
  "Strava is off on this server. Register a Strava API app, then add strava to INTEGRATIONS and its STRAVA_CLIENT_ID and STRAVA_CLIENT_SECRET to the .env, and restart.": "Strava jest wyłączona na tym serwerze. Zarejestruj aplikację Strava API, potem dodaj strava do INTEGRATIONS oraz STRAVA_CLIENT_ID i STRAVA_CLIENT_SECRET do .env i uruchom ponownie.",
  "Strava uploads come from your own openGym server, so they need one. Connect this device to it in Account.": "Wysyłka do serwisu Strava idzie z twojego własnego serwera openGym, więc jest on potrzebny. Połącz z nim to urządzenie w sekcji Konto.",
  "Strength workouts too": "Także treningi siłowe",
  "Subscribe to this link in your calendar app. Anyone with it sees your plan, so keep it to yourself.": "Zasubskrybuj ten link w aplikacji kalendarza. Każdy, kto go ma, widzi twój plan, więc zachowaj go dla siebie.",
  "Tempo": "Tempo",
  "Tempo for this set": "Tempo tej serii",
  "Tempo {0}": "Tempo {0}",
  "Tempo {0}, start the guide": "Tempo {0}, uruchom przewodnik",
  "The calendar link is served by your own openGym server, so it needs one. Connect this device to it in Account.": "Link do kalendarza podaje twój własny serwer openGym, więc jest on potrzebny. Połącz z nim to urządzenie w sekcji Konto.",
  "The link stops working at once. What your calendar already shows may stay until it refreshes.": "Link od razu przestanie działać. To, co kalendarz już pokazuje, może zostać do odświeżenia.",
  "The old link stops working, and every calendar that uses it needs the new one.": "Stary link przestanie działać, a każdy kalendarz, który go używa, będzie potrzebował nowego.",
  "The password stays on this device, in its secure storage. It is never synced or put in a backup.": "Hasło zostaje na tym urządzeniu, w bezpiecznym magazynie. Nigdy nie jest synchronizowane ani dodawane do kopii.",
  "The server cannot show this link again. Make a new one.": "Serwer nie może ponownie pokazać tego linku. Utwórz nowy.",
  "This device stops backing up and forgets the password. The backups already in the folder stay there.": "To urządzenie przestanie robić kopie i zapomni hasło. Kopie, które już są w folderze, tam zostaną.",
  "Tick the set": "Odhacz serię",
  "Turn off": "Wyłącz",
  "Turn off the calendar feed?": "Wyłączyć kanał kalendarza?",
  "Up as fast as you can. The guide gives it one quick second.": "W górę najszybciej, jak się da. Przewodnik daje na to jedną szybką sekundę.",
  "Uploading": "Wysyłanie",
  "User name": "Nazwa użytkownika",
  "WebDAV backup": "Kopia WebDAV",
  "When the app is open, at most once a day, on this device.": "Gdy aplikacja jest otwarta, najwyżej raz dziennie, na tym urządzeniu.",
  "Your planned sessions in Apple Calendar, Google Calendar or Outlook, kept up to date. A private link only your calendar knows.": "Zaplanowane treningi w Apple Calendar, Google Calendar lub Outlook, zawsze aktualne. Prywatny link, który zna tylko twój kalendarz.",
  "Your server forgets the sign-in and stops uploading. What is on Strava stays, and the Strava app keeps its access until you remove it on strava.com.": "Twój serwer zapomni logowanie i przestanie wysyłać. To, co jest w serwisie Strava, zostaje, a aplikacja Strava zachowa dostęp, dopóki nie usuniesz go na strava.com.",
  "{0} s per rep, a guide in the workout counts it for you.": "{0} s na powtórzenie, przewodnik w treningu odliczy to za ciebie.",
  "{0} s under tension": "{0} s pod napięciem",
  "{0} s under tension. Lovely and slow.": "{0} s pod napięciem. Pięknie i powoli.",
  "Backups & calendar": "Kopie i kalendarz",
  "A copy every day in your own Nextcloud or any WebDAV folder.": "Kopia codziennie w twoim własnym Nextcloud lub dowolnym folderze WebDAV.",
  "The full backup, once a day while the app is open, and whenever you tap Back up now.": "Pełna kopia raz dziennie, gdy aplikacja jest otwarta, i za każdym razem, gdy dotkniesz Zrób kopię teraz.",
  "Restore it on a new phone in two taps.": "Przywróć ją na nowym telefonie w dwóch dotknięciach.",
  "Your planned sessions in Apple, Google or Outlook calendar.": "Zaplanowane treningi w kalendarzu Apple, Google lub Outlook.",
  "Planned sessions from a week back to eight weeks ahead, as all-day events.": "Zaplanowane treningi od tygodnia wstecz do ośmiu tygodni naprzód, jako wydarzenia całodniowe.",
  "Finished workouts too, if you like.": "Jeśli chcesz, także ukończone treningi.",
  "Your runs, rides and rows go up to Strava, strength too if you like.": "Biegi, jazdy i wiosłowanie trafiają do serwisu Strava, a jeśli chcesz, także siłówka.",
  "Finished cardio workouts, with their time and distance.": "Ukończone treningi cardio, z czasem i dystansem.",
  "Strength sessions as Weight Training, if you switch it on.": "Treningi siłowe jako Trening siłowy, jeśli to włączysz.",
