  "The server did not take that name and password. An app password usually works best.": "Serwer nie przyjął tej nazwy i hasła. Zwykle najlepiej działa hasło aplikacji.",
  "That folder is not there, and openGym could not make it. Make it on the server first.": "Tego folderu nie ma, a openGym nie dał rady go utworzyć. Najpierw utwórz go na serwerze.",
  "The server says this account may not write there.": "Serwer mówi, że to konto nie może tam zapisywać.",
  "The server is out of space for this account.": "Na serwerze skończyło się miejsce dla tego konta.",
  "Could not reach the server. In a browser it also has to allow this site (CORS), see the guide.": "Nie udało się połączyć z serwerem. W przeglądarce musi on też zezwalać tej stronie (CORS), zajrzyj do poradnika.",
  "Type the password again: this device does not have it.": "Wpisz hasło jeszcze raz: to urządzenie go nie ma.",
  "That file is not an openGym backup.": "Ten plik nie jest kopią openGym.",
  "Nothing to back up yet: log a workout first.": "Na razie nie ma czego kopiować: najpierw zapisz trening.",
  "The server answered with an error.": "Serwer odpowiedział błędem.",
  "Paste the address of the folder on your WebDAV server.": "Wklej adres folderu na swoim serwerze WebDAV.",
  "That does not look like an address.": "To nie wygląda na adres.",
  "Leave the name and password out of the address, they have their own fields.": "Nie wpisuj nazwy i hasła do adresu, mają swoje własne pola.",
  "Strava was not given access. Nothing was connected.": "Strava nie dostała dostępu. Nic nie zostało połączone.",
  "Strava has to be allowed to upload activities. Connect again and leave that box ticked.": "Strava musi mieć zgodę na wysyłanie aktywności. Połącz ponownie i zostaw to pole zaznaczone.",
  "That sign-in took too long or came from somewhere else. Start again from here.": "To logowanie trwało za długo albo przyszło skądinąd. Zacznij jeszcze raz stąd.",
  "Sign in to your server first, then connect Strava.": "Najpierw zaloguj się na swój serwer, potem połącz konto Strava.",
  "Strava is off on this server.": "Strava jest wyłączona na tym serwerze.",
  "Strava could not be connected. Try again.": "Nie udało się połączyć konta Strava. Spróbuj ponownie.",
  "Keeps the newest {0} backup, one per day.": "Zachowuje {0} najnowszą kopię, jedną dziennie.",
  "Keeps the newest {0} backups, one per day.": {"one":"Zachowuje {0} najnowszą kopię, jedną dziennie.","few":"Zachowuje {0} najnowsze kopie, po jednej dziennie.","many":"Zachowuje {0} najnowszych kopii, po jednej dziennie.","other":"Zachowuje {0} najnowsze kopie, po jednej dziennie."},
  // --- promises-146: progression rules, shoulder heads and lats, bench, own media ---,
  "Steady double progression": "Równa podwójna progresja",
  "Undulating days": "Falujące dni",
  "Shorter rests": "Krótsze przerwy",
  "Work up a rep range one rep at a time. Every set has to hit the target before it moves, and at the top of the range the weight goes up.": "Wchodź w zakres powtórzeń po jednym. Każda seria musi trafić w cel, zanim ten pójdzie w górę, a na szczycie zakresu rośnie ciężar.",
  "Each session rotates: a medium day at your reps, a heavy day with fewer, a light day with more. The weights come from your estimated max, so they climb as you get stronger.": "Każdy trening się zmienia: średni dzień z twoimi powtórzeniami, ciężki z mniejszą liczbą, lekki z większą. Ciężary biorą się z twojego szacowanego maksa, więc rosną razem z siłą.",
  "Same weight, a bit less rest each time every set is clean. At your shortest rest the weight goes up and the rest starts over.": "Ten sam ciężar, trochę krótsza przerwa za każdym razem, gdy wszystkie serie są czyste. Przy najkrótszej przerwie ciężar rośnie, a przerwa zaczyna się od nowa.",
  "Every set hit {0}. Same weight, {1} reps this time.": "Każda seria zrobiła {0}. Ten sam ciężar, tym razem {1} powtórzeń.",
  "Not every set reached {0} yet. Same weight and target again ({1} of {2} to go).": "Jeszcze nie każda seria zrobiła {0}. Ten sam ciężar i cel jeszcze raz (zostało {1} z {2}).",
  "Every set clean. Same weight with {0}s less rest: {1}s.": "Wszystkie serie czyste. Ten sam ciężar i {0} s krótsza przerwa: {1} s.",
  "Clean at your shortest rest. {0} {1} less help, rest back to {2}s.": "Czysto przy najkrótszej przerwie. {0} {1} mniej pomocy, przerwa wraca do {2} s.",
  "Clean at your shortest rest. {0} {1} more, rest back to {2}s.": "Czysto przy najkrótszej przerwie. {0} {1} więcej, przerwa wraca do {2} s.",
  "Stuck for {0} sessions. Same weight with more rest: {1}s.": "Utknięcie od {0} treningów. Ten sam ciężar i dłuższa przerwa: {1} s.",
  "Missed reps last time. Same weight and rest again ({0} of {1} to go).": "Ostatnio zabrakło powtórzeń. Ten sam ciężar i przerwa jeszcze raz (zostało {0} z {1}).",
  "Heavy day: {0} reps at {1} {2}, from your estimated max of {3} {2}.": "Ciężki dzień: {0} powtórzeń z {1} {2}, z twojego szacowanego maksa {3} {2}.",
  "Light day: {0} reps at {1} {2}, from your estimated max of {3} {2}.": "Lekki dzień: {0} powtórzeń z {1} {2}, z twojego szacowanego maksa {3} {2}.",
  "Medium day: {0} reps at {1} {2}, from your estimated max of {3} {2}.": "Średni dzień: {0} powtórzeń z {1} {2}, z twojego szacowanego maksa {3} {2}.",
  "Rest down to (s)": "Przerwa do (s)",
  "Medium {0} reps · heavy {1} · light {2}": "Średni {0} powt. · ciężki {1} · lekki {2}",
  "Front delts": "Przednie barki",
  "Side delts": "Boczne barki",
