  "Flat, incline and decline. Everything goes.": "Płaska, skośna i ujemna. Wszystko gra.",
  "No incline or decline work in the library or the Coach’s picks.": "Bez ćwiczeń na skosie w bibliotece i w propozycjach Trenera.",
  "Bench work stays out of the library until you get one.": "Ćwiczenia na ławce zostają poza biblioteką, dopóki jej nie masz.",
  "Everything, flat bench only": "Wszystko, tylko płaska ławka",
