  "Your equipment": "Twój sprzęt",
  "Your photo or video": "Twoje zdjęcie lub film",
  "Only you see it. It travels with your account.": "Widzisz je tylko ty. Jest przy twoim koncie.",
  "Show how you do it, on your own machine. Only you see it.": "Pokaż, jak robisz to ty, na swojej maszynie. Widzisz je tylko ty.",
