  "Two happy notes after the tick, when sounds are on.": "Dwa radosne dźwięki po odhaczeniu, gdy dźwięki są włączone.",
  "Type a time like 25:00 or 1:45:00.": "Wpisz czas, np. 25:00 albo 1:45:00.",
  "U.S. Navy tape method. Waist at the navel, neck below the larynx.": "Metoda taśmy U.S. Navy. Talia na wysokości pępka, szyja poniżej krtani.",
  "Under the next set: its share of your best e1RM and the reps a record needs.": "Pod następną serią: jej udział w twoim najlepszym e1RM i powtórzenia potrzebne do rekordu.",
