  "{0} challenge done": "Ukończone wyzwania: {0}",
  "{0} challenges done": {"one":"{0} wyzwanie zaliczone","few":"{0} wyzwania zaliczone","many":"{0} wyzwań zaliczonych","other":"{0} wyzwania zaliczonego"},
  "{0} is in {1} from next time.": "{0} jest w {1} od następnego razu.",
  "{0} is in {1}, on the Skill ladder rule.": "{0} jest w {1}, z zasadą Drabinka umiejętności.",
  "{0} left this year.": {"one":"W tym roku został {0}.","few":"W tym roku zostały {0}.","many":"W tym roku zostało {0}.","other":"W tym roku zostało {0}."},
  "{0} points to level {1}": "{0} pkt do poziomu {1}",
  "{0} streak badge": "Odznaki za serię: {0}",
  "{0} streak badges": {"one":"{0} odznaka za serię","few":"{0} odznaki za serię","many":"{0} odznak za serię","other":"{0} odznaki za serię"},
  "{0} week a year": "{0} tydzień w roku",
  "{0} week trained": "{0} tydzień z treningiem",
  "{0} weeks a year": {"one":"{0} tydzień w roku","few":"{0} tygodnie w roku","many":"{0} tygodni w roku","other":"{0} tygodnia w roku"},
  "{0} weeks trained": {"one":"{0} tydzień treningów","few":"{0} tygodnie treningów","many":"{0} tygodni treningów","other":"{0} tygodnia treningów"},
  "{0}% fewer sets, same weights. Recharge.": "{0}% mniej serii, te same ciężary. Ładuj baterie.",
  "{1} are still recovering, so they sit this one out.": {"one":"{1} wciąż się regeneruje, więc tym razem odpoczywa.","few":"{1} wciąż się regenerują, więc tym razem odpoczywają.","many":"{1} wciąż się regenerują, więc tym razem odpoczywają.","other":"{1} wciąż się regenerują, więc tym razem odpoczywają."},
  "{1} is still recovering, so it sits this one out.": "{1} jeszcze się regeneruje, więc tym razem odpoczywa.",
  "And it stays that way: openGym Offline has no internet permission, so Android blocks anything it might try.": "I tak zostanie: openGym Offline nie ma uprawnienia do internetu, więc Android blokuje wszystko, czego by próbował.",
  "Any of the sounds on your phone.": "Dowolny dźwięk z telefonu.",
  "Back it up now and then in Settings, Data & backup. A file on your phone is the only copy there is.": "Co jakiś czas zrób kopię w Ustawienia, Dane i kopia. Plik na telefonie to jedyna kopia, jaka istnieje.",
  "Closing the app resets the count; the log never leaves the phone.": "Zamknięcie aplikacji zeruje licznik; dziennik nigdy nie opuszcza telefonu.",
  "Counting since {0}, when the app started. Closing the app resets it; the log never leaves the phone.": "Liczone od {0}, gdy aplikacja wystartowała. Zamknięcie ją zeruje; dziennik nigdy nie opuszcza telefonu.",
  "Each reminder can sound different, so you know which one it is before you look.": "Każde przypomnienie może brzmieć inaczej, więc wiesz, które to, zanim spojrzysz.",
  "Everything this app asked the internet for, newest first. The address only, never what was in it.": "Wszystko, o co ta aplikacja pytała internet, od najnowszych. Tylko adres, nigdy treść.",
  "For reading mid-set without your glasses.": "Do czytania w trakcie serii bez okularów.",
  "Larger": "Jeszcze większy",
  "Last at {0}": "Ostatnio o {0}",
  "Latest": "Najnowsze",
  "Less: no sliding, bouncing or snow. Things just appear.": "Mniej: nic nie przesuwa się, nie podskakuje ani nie pada śnieg. Wszystko po prostu się pojawia.",
  "Like the phone": "Jak w telefonie",
  "Mostly your own server, {0}, when there was something to sync.": "Głównie twój własny serwer, {0}, gdy było coś do synchronizacji.",
  "Motion": "Ruch",
  "Network log": "Dziennik sieci",
  "No map search in openGym Offline. Stand in your gym, tap Current location, done.": "W openGym Offline nie ma wyszukiwania na mapie. Stań w siłowni, stuknij Bieżąca lokalizacja, gotowe.",
  "Not a single byte left this phone. Your training is nobody’s business but yours.": "Ani jeden bajt nie opuścił tego telefonu. Twój trening to tylko twoja sprawa.",
  "Nothing yet. Your server hears from this phone when there is something to sync.": "Jeszcze nic. Twój serwer słyszy ten telefon, gdy jest coś do synchronizacji.",
  "Phone default": "Domyślny telefonu",
  "Phone sound": "Dźwięk telefonu",
  "Pick a phone sound…": "Wybierz dźwięk z telefonu…",
  "Showing the last {0}. The count above has them all.": "Ostatnie: {0}. Licznik powyżej ma wszystkie.",
  "Shows up, keeps quiet.": "Pokazuje się, siedzi cicho.",
  "Tap one to hear it. It rings even with the app closed.": "Stuknij, żeby posłuchać. Dzwoni nawet przy zamkniętej aplikacji.",
  "Text size": "Rozmiar tekstu",
  "This is openGym Offline: Android doesn’t even let it on the internet. Want sync? The normal openGym app can do that, next to this one.": "To jest openGym Offline: Android nawet nie wpuszcza go do internetu. Chcesz synchronizacji? Zwykła aplikacja openGym to potrafi, obok tej.",
  "Weigh-ins, measurements and progress photos.": "Ważenia, pomiary i zdjęcia postępów.",
  "Whatever your phone uses for notifications.": "To, czego telefon używa do powiadomień.",
  "When you walk into your gym.": "Gdy wchodzisz do swojej siłowni.",
  "Who": "Kto",
  "Who this app talked to since you opened it.": "Z kim ta aplikacja rozmawiała, odkąd ją otworzyłeś.",
  "Workout days and the nudge when one slips by.": "Dni treningowe i szturchnięcie, gdy któryś przepadnie.",
  "Workout reminders": "Przypomnienia o treningu",
  "openGym Offline has no internet permission. Your training stays on this phone, full stop.": "openGym Offline nie ma uprawnienia do internetu. Twój trening zostaje na tym telefonie, kropka.",
  "openGym Offline never checks for updates, it can’t. New versions come from wherever you got this one.": "openGym Offline nigdy nie szuka aktualizacji, nie może. Nowe wersje są tam, skąd masz tę.",
  "openGym Offline, no internet permission": "openGym Offline, bez uprawnienia do internetu",
  "openGym Offline: on this phone, and only here": "openGym Offline: na tym telefonie i tylko tu",
  "openGym sounds": "Dźwięki openGym",
  "{0} request this session": "{0} żądanie w tej sesji",
  "{0} requests this session": {"one": "{0} żądanie w tej sesji", "few": "{0} żądania w tej sesji", "many": "{0} żądań w tej sesji", "other": "{0} żądania w tej sesji"},
  "From the app": "Z aplikacji",
  "From the phone itself": "Z samego telefonu",
