  // --- WebDAV backup on a shared device (qa2-146) ---
  "This backup belongs to another account": "Ta kopia należy do innego konta",
  "Someone else set it up on this device, so nothing of yours goes to their folder. Disconnect it to set up your own.": "Ktoś inny ustawił ją na tym urządzeniu, więc nic twojego nie trafia do jego folderu. Odłącz ją, żeby ustawić własną.",
  "Routine from a past workout": "Rutyna z wcześniejszego treningu",
  "From a past workout": "Z wcześniejszego treningu",
  "Pick one you did, imported ones too. Its exercises and sets become a routine you can tweak.": "Wybierz trening, który zrobiłeś, także zaimportowany. Jego ćwiczenia i serie staną się rutyną do poprawienia.",
  "That workout has no exercises to copy.": "Ten trening nie ma ćwiczeń do skopiowania.",
  "Saved as a routine. Your workout stays as it was.": "Zapisano jako rutynę. Twój trening zostaje bez zmian.",
  "Nothing logged yet. Train once, or import your history, and it shows up here.": "Jeszcze nic nie zapisano. Zrób jeden trening albo zaimportuj historię, a pojawi się tutaj.",
  // --- text size and forgotten workouts (watch-polish-146) ---
  "Smallest": "Najmniejszy",
  "Largest": "Największy",
  "Follows your phone’s text size, now {0}.": "Idzie za rozmiarem tekstu w telefonie, teraz {0}.",
  "Big enough to read from the bench.": "Wystarczająco duży, by czytać z ławeczki.",
  "Heavy squats, then pizza.": "Ciężkie przysiady, potem pizza.",
  "This is how the app reads now.": "Tak teraz czyta się aplikację.",
  "font text size bigger smaller letters": "czcionka tekst rozmiar większy mniejszy litery",
  "forgotten workout auto finish": "zapomniany trening automatyczne zakończenie",
  "Ask “Still training?”": "Pytaj „Jeszcze trenujesz?”",
  "End by itself when I leave the gym": "Kończ sam, gdy wychodzę z siłowni",
  "Time to answer": "Czas na odpowiedź",
  "Finish the workout you’re on first, then reopen this one.": "Najpierw skończ trening, który trwa, potem otwórz ten ponownie.",
  "Back in the workout. Pick up where you left off.": "Z powrotem w treningu. Działaj od miejsca, gdzie skończyłeś.",
  "Ended by itself when you left the gym": "Zakończony sam, gdy wyszedłeś z siłowni",
  "Ended by itself after a quiet spell": "Zakończony sam po chwili ciszy",
  "Saved as ending at {0}, after your last set and its rest.": "Zapisany z końcem o {0}, po ostatniej serii i jej przerwie.",
  "Reopen workout": "Otwórz trening ponownie",
  "Still training?": "Jeszcze trenujesz?",
  "No set for {0} minutes. If you’re done, I’ll wrap it up in {1} minutes, ending at your last set.": "Brak serii od {0} min. Jeśli to koniec, zamknę go za {1} min, z końcem na ostatniej serii.",
  "Looks like you left the gym": "Wygląda na to, że wyszedłeś z siłowni",
  "Finish the workout now? Otherwise it ends by itself in {0} minutes.": "Zakończyć trening teraz? Inaczej skończy się sam za {0} min.",
  "Keep going": "Dalej",
  "Finish now": "Zakończ teraz",
  "Finish the workout now? Otherwise it ends by itself at {0}.": "Zakończyć trening teraz? Inaczej skończy się sam o {0}.",
  "Nothing logged for a while. If you’re done, it ends by itself at {0}, saved at your last set.": "Od dłuższej chwili nic nie zapisano. Jeśli to koniec, skończy się sam o {0}, zapisany na ostatniej serii.",
  "Forgotten workouts": "Zapomniane treningi",
  "If nobody answers, it finishes by itself and never throws anything away. The end is your last set plus its rest, so the time stays honest. Reopen it from History for a day. Your watch asks too.": "Jeśli nikt nie odpowie, kończy się sam i nigdy niczego nie wyrzuca. Koniec to ostatnia seria plus jej przerwa, żeby czas był uczciwy. Możesz go ponownie otworzyć z historii przez jeden dzień. Zegarek też pyta.",
  "Never asks and never ends one by itself.": "Nigdy nie pyta i nigdy niczego sam nie kończy.",
  "The default. Long enough for a chat at the water fountain.": "Domyślnie. Wystarczy na pogawędkę przy dystrybutorze wody.",
  "Asks the moment your phone walks out of your gym, then wraps up.": "Pyta, gdy tylko telefon wyjdzie z twojej siłowni, a potem kończy.",
  "Needs the gym reminder: {0}.": "Wymaga przypomnienia o siłowni: {0}.",
  "Save to Photos": "Zapisz w Zdjęciach",
  "Save image": "Zapisz obraz",
  "Saved to Photos": "Zapisano w Zdjęciach",
  "Could not save the picture.": "Nie udało się zapisać obrazu.",
  "openGym may not add pictures to Photos. You can allow it in the phone settings.": "openGym nie może dodawać obrazów do Zdjęć. Możesz na to zezwolić w ustawieniach telefonu.",
  // --- the live widget builder (session-widgets-146) ---
  "A preset sets every surface. Then change whatever you like.": "Szablon ustawia każde miejsce. Potem zmień, co chcesz.",
  "Add a button": "Dodaj przycisk",
  "Add a tile": "Dodaj kafelek",
  "Android": "Android",
  "Android allows three buttons on a notification. Three it is.": "Android pozwala na trzy przyciski w powiadomieniu. Niech będą trzy.",
  "As many as you like. They wrap onto new rows.": "Ile chcesz. Przechodzą do nowych rzędów.",
  "Buttons": "Przyciski",
  "Dynamic Island": "Dynamic Island",
  "Four buttons fit on the Lock Screen.": "Na ekranie blokady mieszczą się cztery przyciski.",
  "Home Screen widget": "Widżet na ekranie głównym",
  "In the app": "W aplikacji",
  "Lifter": "Siłownia",
  "Live widget": "Widżet na żywo",
  "Lock Screen": "Ekran blokady",
  "Lock Screen, notification, the workout card": "Ekran blokady, powiadomienie, karta treningu",
  "Long-press view": "Widok po długim naciśnięciu",
  "Minimal": "Minimum",
  "Needs iOS 17 or later. No animations on the Lock Screen, so the exercise picture is a still. Buttons work without unlocking, Finish opens the app.": "Wymaga iOS 17 lub nowszego. Na ekranie blokady nie ma animacji, więc obraz ćwiczenia jest nieruchomy. Przyciski działają bez odblokowania, Zakończ otwiera aplikację.",
  "No buttons. A tap on it opens openGym.": "Brak przycisków. Stuknięcie otwiera openGym.",
  "No room on the Lock Screen. Apple keeps Live Activities to about 160 points tall.": "Na ekranie blokady nie ma już miejsca. Apple trzyma aktywności na żywo na około 160 punktach wysokości.",
  "No tiles yet.": "Jeszcze bez kafelków.",
  "Nothing here yet, so the workout screen stays as it is. Add a tile or pick a preset.": "Na razie nic tu nie ma, więc ekran treningu zostaje bez zmian. Dodaj kafelek albo wybierz szablon.",
  "Opens openGym, since saving asks what to keep.": "Otwiera openGym, bo przy zapisie pyta, co zachować.",
  "Six tiles fit in a notification before it starts mumbling.": "Sześć kafelków mieści się w powiadomieniu, zanim zacznie mamrotać.",
  "Size of {0}": "Rozmiar: {0}",
  "The Dynamic Island holds four tiles. It is an island, not a continent.": "Dynamic Island mieści cztery kafelki. To wyspa, nie kontynent.",
  "The pill": "Pigułka",
  "The pill has two spots, one each side of the camera.": "Pigułka ma dwa miejsca, po jednym z każdej strony aparatu.",
  "The pill shows two tiles beside the camera. Long-press it for the rest.": "Pigułka pokazuje dwa kafelki przy aparacie. Przytrzymaj, by zobaczyć resztę.",
  "The widget fits three lines under the set.": "Widżet mieści trzy wiersze pod serią.",
  "Three buttons fit in the Dynamic Island.": "W Dynamic Island mieszczą się trzy przyciski.",
  "Tiles": "Kafelki",
  "Tiles become lines of text, so Android 16 can keep it a Live Update by the clock. While a rest runs, the notification shows its rest buttons.": "Kafelki stają się wierszami tekstu, żeby Android 16 mógł zostawić je jako Live Update przy zegarze. W czasie przerwy powiadomienie pokazuje swoje przyciski przerwy.",
  "Up to three lines under the set. The widget keeps its own − and + buttons.": "Do trzech wierszy pod serią. Widżet zachowuje własne przyciski − i +.",
  "Where it shows": "Gdzie się pokazuje",
  "Work set": "Seria robocza",
