  // --- AI Coach 1.4.5: setup, actions, data switches, connector (coach-146) ---
  "Add it as a custom connector in Claude or ChatGPT and sign in with openGym when it asks. Other assistants take a token from below.": "Dodaj go jako własny łącznik w Claude lub ChatGPT i zaloguj się przez openGym, gdy poprosi. Inni asystenci biorą token z listy poniżej.",
  "Add “{0}” to my plan": "Dodaj „{0}” do mojego planu",
  "Add “{0}” to your exercises": "Dodaj „{0}” do swoich ćwiczeń",
  "Added to your exercises": "Dodano do twoich ćwiczeń",
  "After you say yes, it goes back to {0}. Only say yes if you just started this there.": "Gdy się zgodzisz, wróci do {0}. Zgódź się tylko wtedy, gdy przed chwilą zacząłeś to tam.",
  "Back to openGym": "Wróć do openGym",
  "Choose what it may read, and whether it may search the web": "Wybierz, co może czytać i czy może szukać w sieci",
  "Claude, with an API key": "Claude z kluczem API",
  "Code from OpenRouter": "Kod z OpenRoutera",
  "Daily check-ins, sleep, resting heart rate, HRV and steps from your phone, and blood pressure. Off until you switch it on.": "Codzienne check-iny, sen, tętno spoczynkowe, HRV i kroki z telefonu oraz ciśnienie. Wyłączone, dopóki tego nie włączysz.",
  "Estimated one-rep maxes of your main lifts over the last twelve weeks.": "Szacowany ciężar maksymalny głównych ćwiczeń z ostatnich dwunastu tygodni.",
  "Find it for me": "Znajdź za mnie",
  "For questions that need facts from outside your training, like a study or a product.": "Do pytań, które wymagają faktów spoza twojego treningu, jak badanie czy produkt.",
  "From the routines library": "Z biblioteki planów",
  "GPT, with an API key": "GPT z kluczem API",
  "Gemini, with a free tier to start": "Gemini z darmowym pakietem na start",
  "Get a key from {0}": "Pobierz klucz z {0}",
  "Health and how you feel": "Zdrowie i samopoczucie",
  "How it’s done": "Jak to zrobić",
  "It shows up under Settings → API tokens, where you can revoke it any time.": "Pojawi się w Ustawienia → Tokeny API, gdzie możesz go w każdej chwili cofnąć.",
  "Looks for Ollama, LM Studio and llama.cpp on the machine running your openGym server and on this phone.": "Szuka Ollamy, LM Studio i llama.cpp na maszynie z twoim serwerem openGym i na tym telefonie.",
  "Nothing answered. Type its address below, like http://192.168.1.20:11434.": "Nic nie odpowiedziało. Wpisz adres poniżej, np. http://192.168.1.20:11434.",
  "Ollama or LM Studio at home, nothing leaves your Wi-Fi": "Ollama lub LM Studio w domu, nic nie wychodzi poza twoje Wi-Fi",
  "On my network": "W mojej sieci",
  "One sign-in for Claude, GPT, Gemini and more": "Jedno logowanie do Claude, GPT, Gemini i innych",
  "OpenRouter makes a key just for this phone, billed to your OpenRouter credits. You can revoke it there any time.": "OpenRouter tworzy klucz tylko dla tego telefonu, rozliczany z twoich kredytów OpenRouter. Możesz go tam w każdej chwili cofnąć.",
  "Or paste a key": "Albo wklej klucz",
  "Paste a code instead": "Wklej kod zamiast tego",
  "Pick your AI": "Wybierz swoją AI",
  "Remember": "Zapamiętaj",
  "Remember this": "Zapamiętaj to",
  "Saved to what the Coach knows about you": "Zapisane w tym, co Coach o tobie wie",
  "Search the web": "Szukaj w sieci",
  "Should the Coach remember this?": "Czy Coach ma to zapamiętać?",
  "Sign in with OpenRouter": "Zaloguj przez OpenRouter",
  "Signed in with OpenRouter": "Zalogowano przez OpenRouter",
  "Sources": "Źródła",
  "Start it again from the assistant. It only waits ten minutes.": "Zacznij od nowa w asystencie. Czeka tylko dziesięć minut.",
  "Start “{0}” now": "Zacznij „{0}” teraz",
  "Start “{0}” now?": "Zacząć „{0}” teraz?",
