  "Switched off, it is left out of every request from now on.": "Po wyłączeniu od teraz nie trafia do żadnego zapytania.",
  "Test it": "Sprawdź",
  "That doesn’t look like a code from OpenRouter.": "To nie wygląda na kod z OpenRoutera.",
  "That looks like a {0} key, so I switched to {0}.": "To wygląda na klucz {0}, więc przełączyłem na {0}.",
  "That plan isn’t in the library any more.": "Tego planu nie ma już w bibliotece.",
  "That routine is gone.": "Tego planu już nie ma.",
  "The Coach needs these to plan anything at all.": "Bez tego Coach niczego nie zaplanuje.",
  "The OpenRouter sign-in did not work: {0}": "Logowanie przez OpenRouter nie wyszło: {0}",
  "The connection to the AI provider dropped while the Coach was thinking. Try again, ideally on Wi-Fi.": "Połączenie z dostawcą AI zerwało się, gdy Coach myślał. Spróbuj jeszcze raz, najlepiej przez Wi-Fi.",
  "The connection to your AI provider dropped while the Coach was thinking. Try again, ideally on Wi-Fi.": "Połączenie z twoim dostawcą AI zerwało się, gdy Coach myślał. Spróbuj jeszcze raz, najlepiej przez Wi-Fi.",
  "This sign-in has expired": "To logowanie wygasło",
