  "Your AI provider has no web search.": "Twój dostawca AI nie ma wyszukiwania w sieci.",
  "Your latest measurements and the ones from about eight weeks before.": "Twoje najnowsze pomiary i te sprzed około ośmiu tygodni.",
  "Your provider may charge a little per search. The pages it read are linked under its answer.": "Twój dostawca może doliczać drobną opłatę za wyszukiwanie. Przeczytane strony są podlinkowane pod odpowiedzią.",
  "Your server’s admin hasn’t switched this on.": "Administrator twojego serwera tego nie włączył.",
